<script setup>
import { computed,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { studio,getRole,sessionPath } from '../store.js';import Icon from '../components/Icon.vue';const route=useRoute(),router=useRouter(),error=ref('');const p=computed(()=>studio.state.value.plans.find(x=>x.id===route.params.planId));function step(i,checked){const steps=[...p.value.steps];steps[i]=checked;studio.call('updatePractice',p.value.id,{steps})}function retest(){try{const s=studio.call('startRetest',p.value.id);router.push(sessionPath(s))}catch(e){error.value=e.message}}
</script>
<template><template v-if="p"><div class="page-heading"><div><p class="eyebrow">FOCUSED PRACTICE</p><h1>把「{{p.topic}}」讲得更清楚。</h1><p class="muted">{{getRole(p.roleId).title}} · {{p.level}} · 来自上次面试的提升建议</p></div><RouterLink :to="`/interviews/${p.sessionId}/report`" class="text-link">回看原报告 →</RouterLink></div><div class="prepare-grid"><div class="stack"><section class="card"><span class="eyebrow">01 / 理解要点</span><h2>{{p.topic}}</h2><p class="lesson">{{p.lesson}}</p><label class="check-label"><input type="checkbox" :checked="p.steps[0]" @change="step(0,$event.target.checked)">我已阅读并理解关键要点</label></section><section class="card"><span class="eyebrow">02 / 对照思路</span><h2>{{p.question}}</h2><p class="reference">{{p.reference}}</p><label class="check-label"><input type="checkbox" :checked="p.steps[1]" @change="step(1,$event.target.checked)">我能指出原回答中需要补充的部分</label></section><section class="card"><span class="eyebrow">03 / 重新组织</span><label>用自己的话，重新回答<textarea :value="p.draft" @input="studio.call('updatePractice',p.id,{draft:$event.target.value})" rows="6" maxlength="8000" placeholder="结论、依据、具体场景、方案取舍…"/></label><label class="check-label"><input type="checkbox" :checked="p.steps[2]" @change="step(2,$event.target.checked)">我已检查回答中的依据和验证方式</label></section></div><aside class="card preparation-summary sage"><Icon name="sparkle" :size="32"/><h2>再试一次，看看变化。</h2><p>完成三个步骤并写下至少 8 个字的回答，就可以进入同主题再测。</p><progress :value="p.steps.filter(Boolean).length" max="3"/><p>{{p.steps.filter(Boolean).length}} / 3 个步骤 · {{p.draft.length}} 字</p><button class="button dark wide" :disabled="p.status!=='completed'" @click="retest">{{p.retestId?'查看本次再测':'开始专项再测'}} <Icon name="right"/></button><p class="small muted">使用相同题目与规则，帮助回顾表达变化。结果会关联回原报告。</p><p v-if="error" class="error" role="alert">{{error}}</p></aside></div></template><div v-else class="card empty"><h1>练习计划不存在</h1><RouterLink to="/growth">返回成长记录</RouterLink></div></template>
